contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // single public function with inputs to drive calls and send ether
    function run(address payable target, bytes calldata data, uint sendAmount, uint callAmount) public payable {
        require(address(this).balance >= sendAmount + callAmount);

        // Read initial owner and balances
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // 1) Try to call Command with some value from this contract to c
        bool cmdReverted;
        try c.Command{value: callAmount}(target, data) {
            cmdReverted = false;
        } catch {
            cmdReverted = true;
        }

        // 2) Try to call withdraw (may revert if caller != Owner)
        bool withdrawReverted;
        try c.withdraw{value: 0}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // 3) Try multiplicate sending sendAmount
        bool multReverted;
        try c.multiplicate{value: sendAmount}(target) {
            multReverted = false;
        } catch {
            multReverted = true;
        }

        // Read final owner and balance
        address ownerAfter = c.Owner();
        uint balAfter = address(c).balance;

        // General rule asserted for all inputs:
        // - The Owner value never changes due to these external calls (Owner is public and only set at construction in C)
        // - If withdraw succeeded then contract balance must be zero after it
        // - withdraw only succeeds when msg.sender == Owner (in our setup msg.sender is this test contract, so success implies ownerBefore == address(this))
        assert(
            // Owner unchanged
            ownerBefore == ownerAfter
            // If withdraw did not revert then ownerBefore == this contract and balance is zero after
            && (withdrawReverted || (ownerBefore == address(this) && balAfter == 0))
            // If withdraw succeeded then cmd did not change Owner either (redundant but ties to observable state)
            && (withdrawReverted || ownerAfter == ownerBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs to drive calls and send ether
    function run(address payable target, uint sendAmount) public payable {
        // ensure the test contract can forward the requested Ether
        require(address(this).balance >= sendAmount);

        // Observe Owner and contract balance before
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // Call multiplicate forwarding sendAmount
        bool multReverted;
        try c.multiplicate{value: sendAmount}(target) {
            multReverted = false;
        } catch {
            multReverted = true;
        }

        // Observe Owner and contract balance after
        address ownerAfter = c.Owner();
        uint balAfter = address(c).balance;

        // General rule:
        // 1) Owner is not changed by multiplicate (it is only set at construction in C).
        // 2) If multiplicate did not revert and msg.sender (this contract) is not the Owner,
        //    then the contract's balance did not increase compared to before the call.
        //    (i.e., either balance stayed the same or decreased because funds were forwarded out).
        // We cannot refer to msg.sender inside C here, but since calls come from this contract,
        // the condition "this contract is not the Owner" captures non-owner caller behavior.
        assert(
            ownerBefore == ownerAfter
            && (multReverted || ownerBefore == address(this) || balAfter <= balBefore + sendAmount - 0)
        );
    }

    receive() external payable {}
}

