contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: params choose caller addresses via indirect means
    // We'll simulate two roles by using two addresses encoded as bytes and using call to forward
    // Ether to c from this contract and then attempt withdraw/Command as either owner or non-owner
    function run(address payable target, uint256 sendAmount, bytes calldata data) public payable {
        require(address(this).balance >= sendAmount);

        // Capture initial owner and c balance
        address ownerBefore = c.Owner();
        uint256 cBalBefore = address(c).balance;

        // Fund contract c by sending ETH from this test contract
        if (sendAmount > 0) {
            c.f{value: sendAmount}(); // call receive() to deposit
        }

        // After deposit
        uint256 cBalAfter = address(c).balance;

        // Try withdraw and Command as this contract (which is NOT the owner unless owner == address(this))
        bool withdrewAsInvoker;
        bool cmdAsInvokerReverted;
        {
            // attempt withdraw
            try c.withdraw() {
                withdrewAsInvoker = true;
            } catch {
                withdrewAsInvoker = false;
            }

            // attempt Command (no value)
            try c.Command(target, data) {
                cmdAsInvokerReverted = false;
            } catch {
                cmdAsInvokerReverted = true;
            }
        }

        // Now try to call withdraw and Command via the owner: we can only act as owner if owner == address(this).
        // The general rule we assert: if caller != Owner then withdraw and Command must revert; if caller == Owner then withdraw succeeds and transfers full balance out.
        bool callerIsOwner = (ownerBefore == address(this));

        // If this test contract is the owner then withdraw should succeed and reduce c balance to zero
        // and Command should not revert (owner can call it); if not owner both must revert.
        bool withdrawSucceededWhenOwner;
        bool cmdSucceededWhenOwner;

        if (callerIsOwner) {
            // ensure c has some balance to be withdrawn
            // perform withdraw as owner
            try c.withdraw() {
                withdrawSucceededWhenOwner = true;
            } catch {
                withdrawSucceededWhenOwner = false;
            }

            // perform Command as owner (no value)
            try c.Command(target, data) {
                cmdSucceededWhenOwner = true;
            } catch {
                cmdSucceededWhenOwner = false;
            }
        } else {
            // Not owner: emulate expectation values
            withdrawSucceededWhenOwner = false;
            cmdSucceededWhenOwner = false;
        }

        // Read final c balance
        uint256 cBalFinal = address(c).balance;

        // The asserted invariant (general rule):
        // - If this contract is the owner: withdraw should have succeeded and drained the contract (final balance == 0), and Command as owner should not revert.
        // - If this contract is not the owner: both withdraw and Command attempts made by this contract earlier must have reverted (i.e., did not succeed).
        assert(
            (callerIsOwner && withdrawSucceededWhenOwner && cmdSucceededWhenOwner && cBalFinal == 0)
            || (!callerIsOwner && withdrewAsInvoker == false && cmdAsInvokerReverted == true)
        );
    }

    receive() external payable {}
}

