contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    // params:
    //   addr - target address passed to multiplicate
    //   fundAmount - amount to first fund C (so contract has some balance)
    //   callValue - Ether to attach to multiplicate call
    function run(address addr, uint256 fundAmount, uint256 callValue) public payable {
        require(address(this).balance >= fundAmount + callValue);

        // Record initial observable values
        uint256 beforeBal = address(c).balance;
        address owner = c.Owner(); // view call allowed inside function

        // Fund C if requested: top-level state-changing call is performed via call to address(c)
        // Use a plain low-level call (not via C) to invoke receive(), as allowed by constraints.
        if (fundAmount > 0) {
            (bool okFund, ) = address(c).call{value: fundAmount}("");
            require(okFund);
        }

        uint256 afterFundBal = address(c).balance;

        // Now call multiplicate with specified value; must be a top-level statement that changes c
        bool reverted;
        try c.multiplicate{value: callValue}(addr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 finalBal = address(c).balance;

        // General property asserted as one boolean expression:
        // - If callValue < finalBal_beforeCall (i.e., multiplicate's if condition false), then multiplicate must not have transferred funds: finalBal == afterFundBal and call did not revert because require inside not triggered.
        // - If callValue >= balance_before_call then either it transferred all (finalBal == 0) or the call reverted; in either case finalBal is either 0 or unchanged.
        // We observe the balance right before the multiplicate call as afterFundBal.
        uint256 balBeforeCall = afterFundBal;

        assert(
            (
                callValue < balBeforeCall
                && finalBal == balBeforeCall
            )
            || (
                callValue >= balBeforeCall
                && (finalBal == 0 || finalBal == balBeforeCall)
            )
        );
    }

    receive() external payable {}
}

